{"content":"import { createFileRoute } from "@tanstack/react-router";
import { useState, type FormEvent } from "react";
import { Mail, MapPin, Phone, Printer } from "lucide-react";
import { toast } from "sonner";
import { COMPANY, DEFAULT_SALES_REP } from "@/data/company";

export const Route = createFileRoute("/contact")({
  head: () => ({
    meta: [
      { title: "Contact Pickrel Brothers | Plumbing & HVAC Supply, Dayton OH" },
      {
        name: "description",
        content:
          "Call 937-461-5960 or email sales@pickrelbros.com. Pickrel Brothers Inc., 901 S. Perry St., Dayton, OH 45402 — wholesale plumbing, heating and industrial supplies.",
      },
      { property: "og:title", content: "Contact Pickrel Brothers Inc." },
      {
        property: "og:description",
        content: "Reach our Dayton counter and inside sales team by phone, email or contact form.",
      },
    ],
  }),
  component: ContactPage,
});

function ContactPage() {
  const [sent, setSent] = useState(false);

  function onSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setSent(true);
    toast.success("Message sent to Pickrel Brothers");
  }

  return (
    <div className="container-page py-10">
      <h1 className="font-display text-3xl font-bold uppercase text-navy">Contact Pickrel Brothers</h1>
      <p className="mt-2 max-w-3xl text-muted-foreground">
        Call the counter, email sales or send us a note. We answer the phone.
      </p>

      <div className="mt-8 grid gap-8 lg:grid-cols-[1fr_360px]">
        <div className="rounded-md border border-border bg-card p-6 shadow-card">
          {sent ? (
            <div className="py-10 text-center">
              <h2 className="font-display text-2xl font-bold uppercase text-navy">Thanks — we've got it</h2>
              <p className="mx-auto mt-2 max-w-md text-sm text-muted-foreground">
                A Pickrel Brothers sales representative will follow up. If it's urgent, call{" "}
                {COMPANY.phone}.
              </p>
            </div>
          ) : (
            <form onSubmit={onSubmit} className="grid gap-4 sm:grid-cols-2">
              <Field label="Name" name="name" required />
              <Field label="Company" name="company" />
              <Field label="Email" name="email" type="email" required />
              <Field label="Phone" name="phone" type="tel" />
              <label className="sm:col-span-2 text-sm font-semibold text-navy">
                How can we help?
                <textarea
                  name="message"
                  required
                  rows={6}
                  className="mt-1 block w-full rounded-md border border-input bg-card px-3 py-2 text-sm text-foreground"
                  placeholder="Part numbers, quantities, job name, or a description of what you need."
                />
              </label>
              <label className="sm:col-span-2 text-sm font-semibold text-navy">
                Attach a PO, print or photo (optional)
                <input
                  type="file"
                  multiple
                  className="mt-1 block w-full rounded-md border border-input bg-card px-3 py-2 text-sm text-muted-foreground"
                />
              </label>
              <div className="sm:col-span-2">
                <button
                  type="submit"
                  className="rounded-md bg-navy px-6 py-3 font-display font-bold uppercase tracking-wide text-navy-foreground hover:bg-navy-muted"
                >
                  Send message
                </button>
              </div>
            </form>
          )}
        </div>

        <aside className="space-y-4">
          <div className="rounded-md border border-border bg-card p-6 shadow-card">
            <h2 className="font-display text-lg font-bold uppercase text-navy">Pickrel Brothers Inc.</h2>
            <ul className="mt-4 space-y-3 text-sm text-muted-foreground">
              <li className="flex gap-3">
                <MapPin className="mt-0.5 h-4 w-4 shrink-0 text-sky" aria-hidden />
                <span>
                  {COMPANY.address1}
                  <br />
                  {COMPANY.address2}
                </span>
              </li>
              <li className="flex gap-3">
                <Phone className="mt-0.5 h-4 w-4 shrink-0 text-sky" aria-hidden />
                <a href={COMPANY.phoneHref} className="font-semibold text-foreground hover:text-sky">
                  {COMPANY.phone}
                </a>
              </li>
              <li className="flex gap-3">
                <Printer className="mt-0.5 h-4 w-4 shrink-0 text-sky" aria-hidden />
                <span>Fax {COMPANY.fax}</span>
              </li>
              <li className="flex gap-3">
                <Mail className="mt-0.5 h-4 w-4 shrink-0 text-sky" aria-hidden />
                <a href={`mailto:${COMPANY.email}`} className="hover:text-sky">
                  {COMPANY.email}
                </a>
              </li>
            </ul>
            <p className="mt-4 text-xs text-muted-foreground">{COMPANY.hours}</p>
          </div>

          <div className="rounded-md border-2 border-sky bg-sky-soft p-6">
            <h2 className="font-display text-lg font-bold uppercase text-navy">Contact your sales rep</h2>
            <p className="mt-3 text-sm font-semibold text-navy">{DEFAULT_SALES_REP.name}</p>
            <p className="text-xs text-navy-muted">{DEFAULT_SALES_REP.title}</p>
            <p className="mt-2 text-xs text-navy-muted">
              Account customers are assigned a dedicated representative. Sign in to see yours.
            </p>
            <div className="mt-4 flex flex-col gap-2">
              <a
                href={DEFAULT_SALES_REP.phoneHref}
                className="rounded-md bg-navy px-4 py-2 text-center text-sm font-semibold text-navy-foreground hover:bg-navy-muted"
              >
                Call {DEFAULT_SALES_REP.phone}
              </a>
              <a
                href={`mailto:${DEFAULT_SALES_REP.email}`}
                className="rounded-md border-2 border-navy px-4 py-2 text-center text-sm font-semibold text-navy hover:bg-card"
              >
                Email your rep
              </a>
            </div>
          </div>
        </aside>
      </div>
    </div>
  );
}

function Field({
  label,
  name,
  type = "text",
  required = false,
}: {
  label: string;
  name: string;
  type?: string;
  required?: boolean;
}) {
  return (
    <label className="text-sm font-semibold text-navy">
      {label}
      {required && <span className="text-destructive"> *</span>}
      <input
        name={name}
        type={type}
        required={required}
        className="mt-1 block h-11 w-full rounded-md border border-input bg-card px-3 text-sm text-foreground"
      />
    </label>
  );
}
